class ApiKeyGuard
  def initialize(app, header: "X-Api-Key")
    @app, @header = app, header
  end

  def call(env)
    return [401, { "content-type" => "text/plain" }, ["unauthorized"]] \
      unless env["HTTP_#{@header.upcase.tr('-', '_')}"]
    @app.call(env)                      # forward to the next middleware
  end
end

